13	  h1 { font-size: 20px; margin: 0 }
14	  .dd { position: relative; font-size: 14px }
15	  .dd-toggle { display: flex; align-items: center; gap: 8px; padding: 9px 14px; background: #fff; border: 1px solid #c9ced6; border-radius: 7px; cursor: pointer; user-select: none }
16	  .dd-toggle .caret { font-size: 10px; color: #6a7280 }
17	  .dd-list { position: absolute; right: 0; top: calc(100% + 6px); width: 200px; background: #fff; border: 1px solid #c9ced6; border-radius: 8px; box-shadow: 0 8px 20px rgba(24, 30, 40, 0.12); display: none; z-index: 5 }
18	  .dd-list.open { display: block }
19	  .dd-option { padding: 10px 14px; cursor: pointer }
20	  .dd-option:hover { background: #eef1f5 }
21	  .dd-option:focus-visible { outline: 2px solid #2456c4; outline-offset: -2px }
22	  .dd-option.active { background: #eef1f5 }
23	  .dd-toggle:focus-visible { outline: 2px solid #2456c4; outline-offset: 2px }
