25	  .result h2 { font-size: 16px; margin: 0 0 6px }
26	  .result h2 a { color: #2456c4; text-decoration: none }
27	  .result p { margin: 0; font-size: 14px; color: #4d5663; line-height: 1.55 }
28	</style>
