30	  window.__activated = []
31	  document.addEventListener('click', function (e) {
32	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
33	    var name = hit ? hit.getAttribute('data-track') : null
34	    if (name) window.__activated.push(name)
35	  })
36	</script>
